export function evaluate({ inputs, time }) {
  const g = 9.8;
  const u = Number(inputs && inputs.launchSpeed != null ? inputs.launchSpeed : 3);
  const show = !(inputs && inputs.showArrows === 'off');
  const tA = u / g;
  const tEnd = 2 * u / g;
  const t = sdk.clamp(Number(time) || 0, 0, tEnd);
  let v = u - g * t;
  if (Math.abs(v) < 1e-9) v = 0;
  let h = u * t - g * t * t / 2;
  if (Math.abs(h) < 1e-12) h = 0;
  const a = -g;
  const hTop = u * u / (2 * g);
  const released = t >= tA - 1e-9;
  const dtr = released ? Math.max(0, t - tA) : 0;
  let vh = released ? -g * dtr : 0;
  if (Math.abs(vh) < 1e-9) vh = 0;
  const hh = released ? -g * dtr * dtr / 2 : 0;

  const S = 110;
  const launchY = 200;
  const yOf = (m) => launchY - m * S;
  const xT = 240, xH = 460, axisX = 60;
  const off = 45;
  const objs = [];

  objs.push(sdk.text('axisTitle', axisX - 30, 28, 'height (m), up +', { align: 'start' }));
  objs.push(sdk.line('axis', axisX, yOf(1.35), axisX, yOf(-1.35)));
  [-1, 0, 1].forEach((m) => {
    const id = m < 0 ? 'm1' : (m === 0 ? 'z0' : 'p1');
    objs.push(sdk.line('tick_' + id, axisX - 6, yOf(m), axisX + 6, yOf(m)));
    objs.push(sdk.text('tickL_' + id, axisX - 14, yOf(m) + 5, String(m), { align: 'middle' }));
  });

  objs.push(sdk.text('nameT', xT, 28, 'Tossed ball', { align: 'middle' }));
  objs.push(sdk.text('nameH', xH, 28, 'Held ball', { align: 'middle' }));

  objs.push(...sdk.groundMark('launch', xT, launchY + 13, 60));
  objs.push(sdk.text('launchText', axisX + 14, launchY + 18, 'Launch mark', { align: 'start' }));

  const yTop = yOf(hTop);
  objs.push({ kind: 'line', id: 'apexLine', from: { x: xT - 32, y: yTop }, to: { x: xT + 32, y: yTop }, role: 'neutral', opacity: 0.5 });
  objs.push(sdk.text('apexText', xT + 60, yTop + 5, 'top ' + sdk.format(hTop, 3) + ' m', { align: 'start' }));

  objs.push(...sdk.gate('gate', xH, launchY + 13, { open: released }));
  objs.push(sdk.text('gateText', xH + 62, launchY + 18, 'Release gate', { align: 'start' }));

  const yT = yOf(h);
  const yH = yOf(hh);
  objs.push(sdk.circle('ballT', xT, yT, 24, { role: 'input' }));
  objs.push(sdk.circle('ballH', xH, yH, 24, { role: 'observed' }));

  if (show) {
    objs.push(sdk.circle('vDotT', xT - off, yT, 6, { role: 'output' }));
    objs.push(...sdk.vector('vT', { x: xT - off, y: yT }, { value: Math.abs(v), direction: v >= 0 ? 'up' : 'down' }, { scale: 10, label: 'v', role: 'output' }));
    objs.push(...sdk.vector('aT', { x: xT + off, y: yT }, { value: Math.abs(a), direction: 'down' }, { scale: 4.5, label: 'a', role: 'warning' }));
    objs.push(sdk.circle('vDotH', xH - off, yH, 6, { role: 'output' }));
    objs.push(...sdk.vector('vH', { x: xH - off, y: yH }, { value: Math.abs(vh), direction: vh >= 0 ? 'up' : 'down' }, { scale: 10, label: 'v', role: 'output' }));
    if (released) {
      objs.push(...sdk.vector('aH', { x: xH + off, y: yH }, { value: g, direction: 'down' }, { scale: 4.5, label: 'a', role: 'warning' }));
    }
  }

  const readouts = [
    { id: 'tossedHeight', value: h },
    { id: 'tossedVelocity', value: v },
    { id: 'tossedAcceleration', value: a }
  ];
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: readouts },
    quantities: {
      launchSpeed: u, gravity: g, velocity: v, acceleration: a, apexTime: tA, height: h,
      tossedHeight: h, tossedVelocity: v, tossedAcceleration: a
    }
  };
}
